// server tiruan: path -> [status, data, lama ms]
const rute = { "/produk": [200, '[{"id":1,"nama":"Kopi"}]', 50], "/stok": [200, '{"1":12}', 80], "/lambat": [200, "{}", 2000] };
const fetchTiruan = (path, { signal } = {}) => new Promise((resolve, reject) => {
  const [status, teks, ms] = rute[path] ?? [404, '{"error":"tidak ada"}', 30];
  const t = setTimeout(() => resolve({ ok: status < 400, status, json: async () => JSON.parse(teks) }), ms);
  signal?.addEventListener("abort", () => { clearTimeout(t); reject(new DOMException("dibatalkan", "AbortError")); });
});

async function ambil(path, ms = 500) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), ms);
  try {
    const res = await fetchTiruan(path, { signal: ctrl.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status} untuk ${path}`);
    return await res.json();
  } finally { clearTimeout(t); }
}
const [produk, stok] = await Promise.all([ambil("/produk"), ambil("/stok")]);
console.log(produk[0].nama, "stok", stok[produk[0].id]);
try { await ambil("/tidak-ada"); } catch (e) { console.log("gagal:", e.message); }
try { await ambil("/lambat"); } catch (e) { console.log("gagal:", e.name === "AbortError" ? "timeout /lambat" : e.message); }

