  name: "toko-kopi", version: "1.2.0", type: "module",
  scripts: { dev: "vite", build: "vite build", test: "vitest run", lint: "eslint ." },
  dependencies: { react: "^19.0.0", "react-dom": "^19.0.0" },
  devDependencies: { vite: "^6.0.0", vitest: "^3.0.0", eslint: "~9.17.0" },
};
function cocok(rentang, versi) {
  const op = rentang[0];                                   // "^", "~", atau angka
  const dasar = op === "^" || op === "~" ? rentang.slice(1) : rentang;
  const [M, m, p] = dasar.split(".").map(Number);
  const [maj, min, pat] = versi.split(".").map(Number);
  if (op === "^") return maj === M && (min > m || (min === m && pat >= p));
  if (op === "~") return maj === M && min === m && pat >= p;
  return versi === dasar;
}
const uji = [["^19.0.0", "19.2.1"], ["^19.0.0", "20.0.0"], ["~9.17.0", "9.17.3"], ["~9.17.0", "9.18.0"]];
for (const [rentang, v] of uji) console.log(`${rentang} menerima ${v}?`, cocok(rentang, v));
